INSERT INTO `#__guidedtours` (`title`, `uid`, `description`, `ordering`, `extensions`, `url`, `created`, `created_by`, `modified`, `modified_by`, `published`, `language`, `note`, `access`, `autostart`) VALUES ('SEF-Adressen', 'joomlaguide-sef-urls-de', '<p>Suchmaschinenfreundliche Adressen (SEF-URLs) machen die Links deiner Website kurz und lesbar: Joomla bildet sie aus den Aliasen deiner Menüeinträge und Inhalte statt aus langen Parameterlisten.</p><p>In dieser Tour schaltest du SEF-URLs in der Konfiguration ein. Dieser Playground startet mit ausgeschalteten SEF-URLs, damit du den Unterschied siehst.</p><p>Sieh dir vorher deine Website an: Klicke oben in der Kopfzeile auf die Schaltfläche mit dem Namen deiner Website (im Joomla Playground auch auf <strong>Site</strong> in seiner Werkzeugleiste). Klicke im Menü auf <strong>Wer wir sind</strong> und sieh dir die Adresse an: etwa <code>index.php?option=com_content&amp;view=article&amp;id=1&amp;Itemid=102</code>.</p><p>Diese Tour folgt dem Tutorial <a href="https://guide.joomla.org/de/tutorials/inhaltsverwaltung/8-adressen/8-1-sef-adressen" target="_blank" rel="noopener">8.1 SEF-Adressen</a> der Joomla-Benutzerdokumentation.</p>', 1, '["com_cpanel","com_config"]', 'administrator/index.php', CURRENT_TIMESTAMP(), 0, CURRENT_TIMESTAMP(), 0, 1, '*', 'Joomla User Guide: 8.1 SEF URLs', 1, 1);
